const cloneInvoice = (inv) => ({
  ...inv,
  lineItems: inv.lineItems.map((l) => ({ ...l })),
  creditAllocations: inv.creditAllocations.map((a) => ({ ...a }))
});

/**
 * Creates a stateful settlement registry; input grants are cloned.
 */
export function createSettlementRegistry(initialGrants = []) {
  if (!Array.isArray(initialGrants)) {
    throw new LedgerError(ERROR_CODES.ERR_INVALID_CONFIG, 'initialGrants must be an array');
  }
  return { grants: initialGrants.map((g) => ({ ...g })), invoices: new Map() };
}

/**
 * Builds an invoice against active registry grants, debits them, and records it.
 */
export function settleInvoice(registry, invoiceParams = {}) {
  const { invoiceId, asOfMs = 0 } = invoiceParams;
  if (registry.invoices.has(invoiceId)) {
    throw new LedgerError(ERROR_CODES.ERR_INVALID_CONFIG, `invoice already settled: ${invoiceId}`);
  }
  const active = selectActiveGrantsOrdered(registry.grants, asOfMs);
  const invoice = buildInvoice({ ...invoiceParams, grants: active });
  registry.invoices.set(invoiceId, invoice);
  return cloneInvoice(invoice);
}

/**
 * Voids a settled invoice and restores its credit allocations.
 */
export function voidInvoiceSettlement(registry, invoiceId, voidedAtMs) {
  const invoice = registry.invoices.get(invoiceId);
  if (!invoice) {
    throw new LedgerError(ERROR_CODES.ERR_UNKNOWN_INVOICE, `unknown invoice: ${invoiceId}`);
  }
  if (invoice.status === INVOICE_STATUS.VOIDED) {
    throw new LedgerError(ERROR_CODES.ERR_ALREADY_VOIDED, `invoice already voided: ${invoiceId}`);
  }
  const { restoredActiveCents, restoredExpiredCents } = restoreAllocations(
    registry.grants,
    invoice.creditAllocations,
    voidedAtMs
  );
  invoice.status = INVOICE_STATUS.VOIDED;
  const reversalWireDigest = encodeFrozenWireDigest({ ...invoice, status: INVOICE_STATUS.VOIDED });
  return {
    invoiceId,
    status: INVOICE_STATUS.VOIDED,
    voidedAtMs,
    netDeltaCents: invoice.totalDueCents === 0 ? 0 : -invoice.totalDueCents,
    restoredActiveCents,
    restoredExpiredCents,
    reversalWireDigest
  };
}

/**
 * Returns cloned registry state; poolBalance counts only grants active at asOfMs.
 */
export function getRegistrySnapshot(registry, asOfMs = 0) {
  const active = selectActiveGrantsOrdered(registry.grants, asOfMs);
  return {
    invoices: [...registry.invoices.values()].map(cloneInvoice),
    grants: registry.grants.map((g) => ({ ...g })),
    poolBalance: summarizePoolBalance(active, asOfMs)
  };
}
