/**
 * Returns the registry's own grant objects that are usable at asOfMs,
 * ordered by expiresAtMs ASC, grantId ASC.
 */
export function selectActiveGrantsOrdered(grants = [], asOfMs = 0) {
  return grants
    .filter(
      (g) =>
        g &&
        g.remainingCents > 0 &&
        (g.effectiveFromMs === undefined || g.effectiveFromMs <= asOfMs) &&
        asOfMs < g.expiresAtMs
    )
    .sort((a, b) => {
      if (a.expiresAtMs !== b.expiresAtMs) return a.expiresAtMs - b.expiresAtMs;
      if (a.grantId < b.grantId) return -1;
      if (a.grantId > b.grantId) return 1;
      return 0;
    });
}

/**
 * Restores allocation cents to their grants (mutating them) and splits the
 * restored total by whether each grant is still unexpired at voidedAtMs.
 */
export function restoreAllocations(grants, allocations = [], voidedAtMs = 0) {
  let restoredActiveCents = 0;
  let restoredExpiredCents = 0;
  for (const alloc of allocations) {
    const grant = grants.find((g) => g && g.grantId === alloc.grantId);
    if (!grant) continue;
    grant.remainingCents += alloc.appliedCents;
    if (voidedAtMs < grant.expiresAtMs) restoredActiveCents += alloc.appliedCents;
    else restoredExpiredCents += alloc.appliedCents;
  }
  return { restoredActiveCents, restoredExpiredCents };
}
